BEGIN;
DO $$
DECLARE admin_id uuid; customer uuid:='88942034-e764-4d39-9e26-ab02856bed40'; provider_user uuid:='b5fe6a6e-b70b-4abd-9407-b3606198d13c'; pid uuid; bid uuid; did uuid; ver timestamptz; cid uuid; res jsonb; key uuid:=gen_random_uuid();
BEGIN
 SELECT user_id INTO admin_id FROM public.user_roles WHERE role='admin' ORDER BY created_at LIMIT 1;
 SELECT id INTO pid FROM public.providers WHERE user_id=provider_user;
 PERFORM set_config('zwits.trusted','on',true);
 UPDATE public.providers SET available=true,id_document_url='dummy/id',selfie_url='dummy/selfie',business_doc_url='dummy/business' WHERE id=pid;
 INSERT INTO public.bookings(customer_id,category,address,description,price,payment_method) VALUES(customer,'cleaning','DUMMY DISPATCH TEST','DUMMY ROLLBACK ONLY',25,'cash') RETURNING id,updated_at INTO bid,ver;
 PERFORM set_config('request.jwt.claim.sub',customer::text,true);
 BEGIN PERFORM public.admin_dispatch_action('booking',bid,ver,gen_random_uuid(),'note','DUMMY note');RAISE EXCEPTION 'FAIL customer admin access';EXCEPTION WHEN OTHERS THEN IF SQLERRM<>'Forbidden' THEN RAISE; END IF; END;
 PERFORM set_config('request.jwt.claim.sub',admin_id::text,true);
 PERFORM public.admin_dispatch_action('booking',bid,ver,key,'hold','DUMMY hold reason');
 IF NOT public.dispatch_job_blocked('booking',bid) THEN RAISE EXCEPTION 'FAIL hold'; END IF;
 res:=public.admin_dispatch_action('booking',bid,ver,key,'hold','DUMMY hold reason');IF res->>'idempotent'<>'true' THEN RAISE EXCEPTION 'FAIL replay'; END IF;
 BEGIN PERFORM public.admin_dispatch_action('booking',bid,ver,gen_random_uuid(),'release','DUMMY release');RAISE EXCEPTION 'FAIL stale';EXCEPTION WHEN OTHERS THEN IF SQLERRM NOT LIKE 'This job changed%' THEN RAISE; END IF; END;
 SELECT updated_at INTO ver FROM public.bookings WHERE id=bid;
 PERFORM public.admin_dispatch_action('booking',bid,ver,gen_random_uuid(),'release','DUMMY release');
 SELECT updated_at INTO ver FROM public.bookings WHERE id=bid;
 PERFORM public.admin_dispatch_action('booking',bid,ver,gen_random_uuid(),'assign','DUMMY manual offer',pid);
 IF (SELECT count(*) FROM public.job_offers WHERE booking_id=bid AND status='offered')<>1 OR (SELECT provider_id FROM public.bookings WHERE id=bid) IS NOT NULL THEN RAISE EXCEPTION 'FAIL manual offer assumes acceptance'; END IF;
 SELECT updated_at INTO ver FROM public.bookings WHERE id=bid;
 res:=public.admin_dispatch_action('booking',bid,ver,gen_random_uuid(),'propose','DUMMY customer approval',NULL,jsonb_build_object('address','DUMMY APPROVED ADDRESS'));
 cid:=(res->>'changeId')::uuid;
 IF (SELECT address FROM public.bookings WHERE id=bid)<>'DUMMY DISPATCH TEST' THEN RAISE EXCEPTION 'FAIL applied before approval'; END IF;
 PERFORM set_config('request.jwt.claim.sub',provider_user::text,true);
 BEGIN PERFORM public.respond_admin_job_change(cid,'approve');RAISE EXCEPTION 'FAIL wrong approver';EXCEPTION WHEN OTHERS THEN IF SQLERRM<>'Forbidden' THEN RAISE; END IF; END;
 PERFORM set_config('request.jwt.claim.sub',customer::text,true);
 PERFORM public.respond_admin_job_change(cid,'approve');
 IF (SELECT address FROM public.bookings WHERE id=bid)<>'DUMMY APPROVED ADDRESS' THEN RAISE EXCEPTION 'FAIL approved edit'; END IF;
 IF (SELECT payment_status FROM public.bookings WHERE id=bid)<>'pending' THEN RAISE EXCEPTION 'FAIL payment changed'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.admin_job_actions WHERE job_id=bid AND before_values->>'address'='DUMMY DISPATCH TEST') THEN RAISE EXCEPTION 'FAIL audit'; END IF;
 PERFORM set_config('request.jwt.claim.sub',admin_id::text,true);
 SELECT updated_at INTO ver FROM public.bookings WHERE id=bid;
 BEGIN PERFORM public.admin_dispatch_action('booking',bid,ver,gen_random_uuid(),'propose','DUMMY illegal state',NULL,'{"status":"completed"}');RAISE EXCEPTION 'FAIL illegal patch';EXCEPTION WHEN OTHERS THEN IF SQLERRM NOT LIKE 'Field is not editable%' THEN RAISE; END IF; END;
 INSERT INTO public.deliveries(customer_id,pickup_address,dropoff_address,pickup_lat,pickup_lng,dropoff_lat,dropoff_lng,service_tier,parcel_size,price,payment_method) VALUES(customer,'DUMMY PICKUP','DUMMY DROP',-17.82,31.05,-17.83,31.06,'express_bike','small',5,'cash') RETURNING id,updated_at INTO did,ver;
 res:=public.admin_dispatch_action('delivery',did,ver,gen_random_uuid(),'propose','DUMMY quote recalculation',NULL,'{"price":999}');cid:=(res->>'changeId')::uuid;
 IF (SELECT (proposed_values->>'price')::numeric FROM public.admin_job_changes WHERE id=cid)=999 THEN RAISE EXCEPTION 'FAIL price trusted'; END IF;
 PERFORM set_config('request.jwt.claim.sub',customer::text,true);PERFORM public.respond_admin_job_change(cid,'approve');
 IF (SELECT payment_status FROM public.deliveries WHERE id=did)<>'pending' OR EXISTS(SELECT 1 FROM public.wallet_transactions WHERE delivery_id=did) THEN RAISE EXCEPTION 'FAIL unpaid settled'; END IF;
END $$;
ROLLBACK;
